const G=(scores,reasonText,evidence,acceptance,repeatOf=null,kind='Geçiş')=>{
 const reasons=reasonText.split('|');
 if(scores.length!==4||reasons.length!==4)throw Error('Four explicit criteria required');
 return {scores,reasons,evidence:evidence.map(([sourceTime,note])=>({sourceTime,note})),acceptance,repeatOf,kind};
};
